const e="toro",a="Antimateria",o="Deuterio",s="BAJO",n="LLENO",i="Desconocido",t="Estadísticas",r="Nave",l="Completado",d="Exportar",c="Importar",u="Recursos",m="Eficiencia",h="Almacenamiento",p="Multiplicador",v="Listo",g="REMOTO",y="Recoger",f="Multiverso",b="nunca",A="Pares",T="Universos",w="Filtrados",x="Actualizar",E="Descartar",P="explorando",S="Remoto",k="Salir",C="Nunca",q="Explorando",L="Prohibido",N="FILTRADO",D="Inicializar",I="Idioma",M="activa",R="inactiva",U="obsoleta",z="archivada",j="desconocida",O="ACTIVA",V="INACTIVA",F="OBSOLETA",B="ARCHIVADA",G="DESCONOCIDA",H="Spam",Y={"Download on the App Store":"Descargar en el App Store",torus:e,"The primordial torus":"El toro primordial","Before time: closed loops of +ε and −ε, everywhere at once. Nothing has begun yet.":"Antes del tiempo: bucles cerrados de +ε y −ε, en todas partes a la vez. Aún no ha empezado nada.","Before time: no star system has formed yet. Only the primordial torus, everywhere at once.":"Antes del tiempo: aún no se ha formado ningún sistema estelar. Solo el toro primordial, en todas partes a la vez.","Did You Know? - Universe Facts":"¿Sabías que…? - Curiosidades del universo","Did you know that...":"¿Sabías que…","Don't show again":"No volver a mostrar","Learn More →":"Más información →",Antimatter:a,"Element 115":"Elemento 115",Deuterium:o,LOW:s,FULL:n,"Atlas Logo":"Logotipo de Atlas","Universal Navigation System":"Sistema de navegación universal","Back to your ship":"Volver a tu nave","MULTIVERSE ONLINE":"MULTIVERSO EN LÍNEA","Quantum Navigation Ready":"Navegación cuántica lista",Unknown:i,"Remote Universe Info":"Información del universo remoto","Remote Universe":"Universo remoto","Unknown Universe":"Universo desconocido","Atlas Node ID":"ID de nodo de Atlas","Remote Seed":"Semilla remota","Not available":"No disponible","Remote Bit Bang (Cosmic Origin Time)":"Bit Bang remoto (hora de origen cósmico)","Return to Your Universe":"Volver a tu universo","Explore more Universes":"Explorar más universos","flashing lights":"luces intermitentes","rapid movements":"movimientos rápidos","intense 3D visual effects":"efectos visuales 3D intensos","The following experience contains %1$@, %2$@, and %3$@.":"La siguiente experiencia contiene %1$@, %2$@ y %3$@.","These may trigger seizures in people with photosensitive epilepsy or similar conditions.":"Pueden provocar crisis en personas con epilepsia fotosensible u otras afecciones similares.","Continuing automatically in":"Continuará automáticamente en","I'm Photosensitive":"Soy fotosensible","Your preference will be saved. You can change it anytime from the footer settings.":"Tu preferencia se guardará. Puedes cambiarla cuando quieras desde los ajustes del pie de página.","Export failed. Please try again.":"No se pudo exportar. Inténtalo de nuevo.","Please select a valid .atl file":"Selecciona un archivo .atl válido","Import failed":"No se pudo importar","Spaceship Control Panel":"Panel de control de la nave","Spaceship Control":"Control de la nave",Stats:t,Ship:r,"Saved (%lld)":"Guardados (%lld)","Daily Challenges":"Retos diarios","Today's Progress":"Progreso de hoy","Day %lld":"Día %lld",Completed:l,"Atlas Size":"Tamaño de Atlas","Saved Locations":"Lugares guardados","Storage Usage":"Uso de almacenamiento","%lld/%lld slots":"%lld/%lld huecos","Complete daily tasks to save more locations":"Completa las tareas diarias para guardar más lugares","Data Management":"Gestión de datos","Export/Import Atlas Data":"Exportar/importar datos de Atlas","%lld/4 keys":"%lld/4 claves",Export:d,Import:c,"Data imported successfully! Reloading...":"¡Datos importados! Recargando…","Saves all localStorage keys to .atl file":"Guarda todas las claves de localStorage en un archivo .atl",Resources:u,"Lv.%lld":"Nv.%lld","Ship Upgrade":"Mejora de la nave",Efficiency:m,Storage:h,Multiplier:p,"Missing resources:":"Recursos que faltan:","Need %lld more %@":"Faltan %lld de %@","MAX LEVEL - Ultimate Spaceship!":"NIVEL MÁXIMO - ¡La nave definitiva!","Upgrade to Level %lld":"Mejorar a nivel %lld","Mining Operations":"Operaciones de minería","Save planets and systems to enable mining operations":"Guarda planetas y sistemas para activar la minería","Generating/hour:":"Producción/hora:","Ready to collect:":"Listo para recoger:","Collect From %@":"Recoger de %@","No saved locations":"No hay lugares guardados","Use the 📍 button to save locations":"Usa el botón 📍 para guardar lugares",Ready:v,"Cannot travel to saved locations from remote universes - return to local universe first":"No puedes viajar a lugares guardados desde universos remotos: vuelve antes a tu universo local",REMOTE:g,"Navigation disabled in remote universe":"Navegación desactivada en universos remotos","Navigate to %@":"Navegar a %@","N/A":"N/D","Manual mining cooldown":"Enfriamiento de minería manual","Ready to mine":"Listo para extraer","Mass Collection":"Recogida masiva","Collect resources from all your saved mining locations at once.":"Recoge de una vez los recursos de todos tus lugares de minería guardados.","Available to collect:":"Disponible para recoger:","Sources: %@":"Fuentes: %@","Collect All":"Recoger todo","Treasure Chest Collected!":"¡Cofre del tesoro recogido!","Lucky find! Extremely rare treasure!":"¡Qué suerte! ¡Un tesoro rarísimo!","Treasure chest is disappearing...":"El cofre del tesoro está desapareciendo…","Treasure Chest - Click for random resources!":"Cofre del tesoro: ¡haz clic para obtener recursos aleatorios!","Treasure Found!":"¡Tesoro encontrado!","You discovered a rare treasure chest!":"¡Has descubierto un cofre del tesoro poco común!","Resources to collect:":"Recursos para recoger:","Lucky find! These chests are extremely rare!":"¡Qué suerte! ¡Estos cofres son rarísimos!",Collect:y,"Created by %@":"Creado por %@","View Atlas source on GitHub":"Ver el código de Atlas en GitHub","Follow on Twitter/X":"Seguir en Twitter/X","Connect on LinkedIn":"Conectar en LinkedIn","Visit %@":"Visitar %@","Explore the Multiverse":"Explora el multiverso",Multiverse:f,"Universe FAQ":"Preguntas frecuentes del universo","Photosensitive Mode":"Modo fotosensible","Disable photosensitive mode":"Desactivar el modo fotosensible","Enable photosensitive mode":"Activar el modo fotosensible","Running it on elsewhereOS?":"¿Lo ejecutas en elsewhereOS?","click to hyperjump":"haz clic para hipersaltar","Remote universe · %@":"Universo remoto · %@","The Core Continuum":"El Core Continuum","Thank you":"Gracias","The Atlas is the work of a great many hours: nights and weekends spent on noise functions, orbits and shaders, on rewriting what was already working because it could be better, and on chasing a universe that would feel real. None of it would exist without the people around it.":"The Atlas es fruto de muchísimas horas: noches y fines de semana dedicados a funciones de ruido, órbitas y shaders, a reescribir lo que ya funcionaba porque podía ser mejor y a perseguir un universo que se sintiera real. Nada de esto existiría sin las personas que lo rodean.","To my family":"A mi familia","For being where it all began, and a living legacy. Thank you for making me who I am today.":"Por ser donde empezó todo, y un legado vivo. Gracias por hacer de mí quien soy hoy.","To my wife, %@":"A mi mujer, %@","For believing in this from the very first star, even when the sheer complexity of it scared her, or when she worried that taking it too far might get me into trouble. And for every hour this universe borrowed from ours.":"Por creer en esto desde la primera estrella, incluso cuando su enorme complejidad la asustaba o cuando temía que llevarlo demasiado lejos me trajera problemas. Y por cada hora que este universo le tomó prestada al nuestro.","To my brother, %@":"A mi hermano, %@","For the ideas, the tests and the honest opinions along the way, and for ignoring me whenever he is not busy being the CTO of HomeDock OS.":"Por las ideas, las pruebas y las opiniones sinceras a lo largo del camino, y por ignorarme siempre que no está ocupado siendo el CTO de HomeDock OS.","To SpaceX and PLD Space":"A SpaceX y PLD Space","For the inspiration: for reminding us, launch after launch, that space is not just something to imagine. Space is love, and we all share the same feeling when we look up. The ships of The Atlas carry their names because they earned it.":"Por la inspiración: por recordarnos, lanzamiento tras lanzamiento, que el espacio no es solo algo que imaginar. El espacio es amor, y todos sentimos lo mismo al mirar hacia arriba. Las naves de The Atlas llevan sus nombres porque se lo han ganado.","And to you":"Y a ti","To everyone who shares this work, or simply takes a moment to look at it. A universe is only worth making if someone comes to explore it. Thank you for being here.":"A todos los que compartís este trabajo, o simplemente os paráis un momento a mirarlo. Un universo solo merece la pena si alguien viene a explorarlo. Gracias por estar aquí.","Unknown origin":"Origen desconocido","Invalid date":"Fecha no válida",never:b,"just now":"ahora mismo","%lldm ago":"hace %lld min","%lldh ago":"hace %lld h","%lldd ago":"hace %lld d","The multiverse did not answer.":"El multiverso no ha respondido.","Network error: %@":"Error de red: %@","P2P universe network":"Red P2P de universos","The Multiverse":"El multiverso",Peers:A,Universes:T,Filtered:w,Refresh:x,"Auto on":"Auto: sí","Auto off":"Auto: no","You are exploring a remote universe":"Estás explorando un universo remoto","Unknown seed":"Semilla desconocida","your universe":"tu universo","Return to your universe":"Volver a tu universo","Private network?":"¿Red privada?","If you're behind a private connection or firewall, open the Atlas ports so other instances can reach yours. That is what lets universes travel across the network.":"Si estás detrás de una conexión privada o un cortafuegos, abre los puertos de Atlas para que otras instancias lleguen a la tuya. Así es como los universos viajan por la red.",Dismiss:E,"Scanning the multiverse…":"Explorando el multiverso…","No other universes found yet. Leave The Atlas running with P2P on: other explorers will appear here as they are discovered.":"Aún no se han encontrado otros universos. Deja The Atlas en marcha con el P2P activado: los demás exploradores aparecerán aquí a medida que se descubran.",exploring:P,"Last seen":"Visto por última vez","%lld Atlas instances":{one:"%lld instancia de Atlas",many:"%lld instancias de Atlas",other:"%lld instancias de Atlas"},"Explore this universe":"Explorar este universo","Returning to":"Volviendo a","Crossing into":"Entrando en","Saved just now":"Guardado ahora mismo","Saved %lld min ago":"Guardado hace %lld min","Saved %lld h ago":"Guardado hace %lld h","Saved %lld d ago":"Guardado hace %lld d","These places belong to your own universe: return home to travel to them.":"Estos lugares pertenecen a tu propio universo: vuelve a casa para viajar a ellos.","Saved places":"Lugares guardados","Stargate links are disabled in remote universes: a gate points into one seed, and this one is not yours. Return to your own universe to open one.":"Los enlaces Stargate están desactivados en los universos remotos: un portal apunta a una semilla, y esta no es la tuya. Vuelve a tu propio universo para abrir uno.","System Error":"Error del sistema","An unexpected error occurred":"Se ha producido un error inesperado","Return to Home":"Volver al inicio","Galaxy map. Click any star to target it, pick a landmark, or follow the green marker back to your ship.":"Mapa galáctico. Haz clic en cualquier estrella para fijarla como objetivo, elige un punto de interés o sigue el marcador verde hasta tu nave.","Click a planet to target it · double-click to go straight into orbit.":"Haz clic en un planeta para fijarlo · doble clic para entrar directamente en órbita.","Click a star to target it · double-click to jump straight there.":"Haz clic en una estrella para fijarla · doble clic para saltar directamente allí.","Show the console":"Mostrar la consola","Hide the console":"Ocultar la consola","Exploring a remote universe from node %@":"Explorando un universo remoto desde el nodo %@",Remote:S,"unknown seed":"semilla desconocida","Back to your own universe":"Volver a tu propio universo",Exit:k,"Universes discovered through the P2P network":"Universos descubiertos a través de la red P2P","P2P universes":"Universos P2P","%@ on X":"%@ en X","Take a photo":"Tomar una foto","Unknown Origin":"Origen desconocido",Never:C,"Just now":"Ahora mismo","Failed to fetch multiverse data":"No se pudieron obtener los datos del multiverso","Scanning Multiverse...":"Explorando el multiverso…","Multiverse Network":"Red del multiverso","Connected P2P Universe Instances":"Instancias de universos P2P conectadas","Total Peers:":"Pares totales:","Valid Universes:":"Universos válidos:","Filtered:":"Filtrados:","Last Update:":"Última actualización:","Auto-refresh: ON":"Actualización automática: SÍ","Auto-refresh: OFF":"Actualización automática: NO","Dismiss message":"Descartar mensaje","Private Network Notice":"Aviso de red privada","If you're behind a private connection or firewall, make sure to open the Atlas ports to allow communication with other multiverse instances. This enables P2P connectivity across the network.":"Si estás detrás de una conexión privada o un cortafuegos, asegúrate de abrir los puertos de Atlas para permitir la comunicación con otras instancias del multiverso. Así se habilita la conectividad P2P en toda la red.","Exploring Remote Universe":"Explorando un universo remoto","Seed:":"Semilla:","Atlas ID:":"ID de Atlas:",Exploring:q,"Bit Bang:":"Bit Bang:","View all %lld instances":{one:"Ver la instancia",many:"Ver las %lld instancias",other:"Ver las %lld instancias"},"Atlas ID":"ID de Atlas","Last Seen":"Visto por última vez","Explore this Universe":"Explorar este universo","Filtered Content":"Contenido filtrado","The following universes contain inappropriate content and have been filtered":"Los siguientes universos contienen contenido inapropiado y se han filtrado",Forbidden:L,FILTERED:N,"Reason: %@":"Motivo: %@","No Multiverse Connections Found":"No se han encontrado conexiones del multiverso","Waiting for P2P peers to connect...":"Esperando a que se conecten pares P2P…","No Data Received":"No se han recibido datos","Check browser console for details":"Consulta la consola del navegador para más detalles","%lld characters at most":{one:"%lld carácter como máximo",many:"%lld caracteres como máximo",other:"%lld caracteres como máximo"},"That seed is not allowed":"Esa semilla no está permitida","The server answered %@":"El servidor respondió %@","The universe could not be created":"No se pudo crear el universo","Awaiting directive":"Esperando instrucciones","Initialization protocol":"Protocolo de inicialización","Will you journey through a shared universe, or forge a new one of your own?":"¿Viajarás por un universo compartido o forjarás uno nuevo y propio?","Seed (optional)":"Semilla (opcional)","Empty for a random seed":"Vacío para una semilla aleatoria","A random seed":"Una semilla aleatoria","Up to %lld characters, or roll the dice":{one:"Hasta %lld carácter, o tira los dados",many:"Hasta %lld caracteres, o tira los dados",other:"Hasta %lld caracteres, o tira los dados"},"Creating…":"Creando…",Initialize:D,"Choose a universe":"Elige un universo","%@. Try again.":"%@. Inténtalo de nuevo.","Other universes can be visited later through the multiverse":"Podrás visitar otros universos más adelante a través del multiverso",Language:I,"THE MULTIVERSE":"EL MULTIVERSO","The Atlas contains 1 sextillion galaxies, 133 times more galaxies than grains of sand on all Earth's beaches?":"The Atlas contiene mil trillones de galaxias, 133 veces más que granos de arena hay en todas las playas de la Tierra?","If you visited a different planet every second, it would take some 95 quintillion years to explore just 0.001% of The Atlas?":"si visitaras un planeta distinto cada segundo, tardarías unos 95 trillones de años en explorar solo el 0,001 % de The Atlas?","A single fully developed elliptical galaxy in The Atlas contains more star systems than our real Milky Way has stars?":"una sola galaxia elíptica plenamente desarrollada de The Atlas contiene más sistemas estelares que estrellas tiene nuestra Vía Láctea real?","The universe cube measures exactly 10 million units on each side, with a unique galaxy at every coordinate point?":"el cubo del universo mide exactamente 10 millones de unidades por lado, con una galaxia única en cada punto de coordenadas?","All galaxies near the center of the universe evolve faster, adding 10 new solar systems per minute from their Bit Bang?":"todas las galaxias cercanas al centro del universo evolucionan más deprisa y suman 10 sistemas solares nuevos por minuto desde su Bit Bang?","If all of humanity explored The Atlas simultaneously, we'd need 12 billion years to see 0.001% of it?":"si toda la humanidad explorara The Atlas a la vez, necesitaríamos 12 000 millones de años para ver el 0,001 %?","The Core Continuum universe began on April 17, 1986, and has been evolving for %@ real years?":"el universo Core Continuum comenzó el 17 de abril de 1986 y lleva %@ años reales evolucionando?","The cosmic origin time becomes the Bit Bang moment for your personal universe?":"la hora de origen cósmico se convierte en el momento del Bit Bang de tu universo personal?","Central galaxies have added over 200 million additional star systems during their evolution on the Core Continuum?":"las galaxias centrales han sumado más de 200 millones de sistemas estelares adicionales durante su evolución en el Core Continuum?","The Singularity Void only appears when someone tries to see beyond 1.9 million years into the past by adjusting cosmic origin time?":"el Vacío de la Singularidad solo aparece cuando alguien intenta ver más de 1,9 millones de años en el pasado ajustando la hora de origen cósmico?","Each of the potential 3×10³² planets has unique characteristics across different planet types?":"cada uno de los 3×10³² planetas posibles tiene características únicas entre los distintos tipos de planeta?","Some planets contain Z-Divinium, an extremely rare and fictional element beyond our real life periodic table?":"algunos planetas contienen Z-Divinio, un elemento ficticio y rarísimo que va más allá de nuestra tabla periódica real?","Planet temperatures vary with their orbits, and gravity is calculated based on real mass physics?":"la temperatura de los planetas varía con su órbita, y la gravedad se calcula según la física real de la masa?","Life forms in The Atlas range from bacteria to non-physical conscious entities and even... Otherworldly beings?":"las formas de vida de The Atlas van desde bacterias hasta entidades conscientes no físicas e incluso… seres de otro mundo?","Some planets have rings if they meet the physical conditions of the real physics behind the Roche limit?":"algunos planetas tienen anillos si cumplen las condiciones físicas reales del límite de Roche?","A fully evolved The Atlas universe after 1.9 million years contains approximately 300 nonillion planets (3 × 10³²)?":"un universo de The Atlas plenamente evolucionado, tras 1,9 millones de años, contiene unos 300 quintillones de planetas (3 × 10³²)?","The Atlas has 500,000 times more galaxies than our entire observable universe?":"The Atlas tiene 500 000 veces más galaxias que todo nuestro universo observable?","A maxed-out The Atlas has 500 million times more star systems than there are real stars in existence?":"un The Atlas al máximo tiene 500 millones de veces más sistemas estelares que estrellas reales existen?","A central galaxy can add 10 million additional systems during The Atlas's maximum evolution period?":"una galaxia central puede sumar 10 millones de sistemas adicionales durante el periodo máximo de evolución de The Atlas?","The Atlas generates approximately 50 nonillion solar systems when the universe is fully developed after 1.9 million years?":"The Atlas genera unos 50 quintillones de sistemas solares cuando el universo está plenamente desarrollado, tras 1,9 millones de años?","If every atom in your body was a habitable planet, you still couldn't represent 1% of the worlds in The Atlas?":"si cada átomo de tu cuerpo fuera un planeta habitable, aun así no llegarías a representar el 1 % de los mundos de The Atlas?","Even if humanity explored The Atlas together for the next 13.8 billion years, we'd see less than 0.0000001% of it?":"aunque la humanidad explorara The Atlas junta durante los próximos 13 800 millones de años, veríamos menos del 0,0000001 %?","The thermal death of our real universe would occur before we could catalog one fully developed The Atlas universe?":"la muerte térmica de nuestro universo real llegaría antes de que pudiéramos catalogar un solo universo de The Atlas plenamente desarrollado?","The Atlas is 500 million times larger than our observable universe, transcending our understanding of reality?":"The Atlas es 500 millones de veces más grande que nuestro universo observable y trasciende nuestra comprensión de la realidad?","A universe created today won't reach full development until the year 1,902,025 AD, 137 times longer than all recorded human history?":"un universo creado hoy no alcanzará su pleno desarrollo hasta el año 1.902.025 d. C., 137 veces más que toda la historia humana registrada?","If a planet has a 4-year orbit and you return after one real year, it will have moved exactly 25% through its orbit?":"si un planeta tiene una órbita de 4 años y vuelves al cabo de un año real, habrá recorrido exactamente el 25 % de su órbita?","You can manipulate time ±15 years in the star system viewer to witness orbital dances unfold in real-time?":"puedes mover el tiempo ±15 años en el visor de sistemas estelares para ver las danzas orbitales en tiempo real?","Two people viewing the same planet at the same moment will see identical cloud formations and weather patterns?":"dos personas que miren el mismo planeta en el mismo momento verán las mismas nubes y el mismo clima?","Every visual element on planets, from storms to volcanoes, is mathematically in sync across all devices worldwide?":"cada elemento visual de los planetas, de las tormentas a los volcanes, está sincronizado matemáticamente en todos los dispositivos del mundo?","Shutting down The Atlas for a week doesn't pause the universe, planets continue orbiting and galaxies keep evolving?":"apagar The Atlas una semana no pausa el universo: los planetas siguen orbitando y las galaxias siguen evolucionando?","The Atlas embodies Einstein's 'Eternalism', all moments in time exist simultaneously in the mathematical structure?":"The Atlas encarna el «eternalismo» de Einstein: todos los instantes del tiempo existen a la vez en la estructura matemática?","Even AWS, Google Cloud, and Azure combined couldn't recalculate a single The Atlas instance's orbital mechanics in real-time?":"ni AWS, Google Cloud y Azure juntos podrían recalcular en tiempo real la mecánica orbital de una sola instancia de The Atlas?","If we lived inside The Atlas, we'd never detect resets or time shifts, our thoughts would be procedurally generated too?":"si viviéramos dentro de The Atlas, nunca detectaríamos reinicios ni saltos en el tiempo, porque nuestros pensamientos también se generarían por procedimientos?","Storing every planet in The Atlas (at 1 byte each) would require 20 trillion times Google's entire data infrastructure?":"almacenar todos los planetas de The Atlas (a 1 byte cada uno) exigiría 20 billones de veces toda la infraestructura de datos de Google?","If you bought hard drives to store The Atlas if each planet were 1 byte, they'd cost $15 sextillion and stack some 630 light years high, far beyond the nearest stars?":"si compraras discos duros para almacenar The Atlas a 1 byte por planeta, costarían 15 000 trillones de dólares y formarían una pila de unos 630 años luz, mucho más allá de las estrellas más cercanas?","The Life Forms analysis presents data inspired by humanity's Arecibo message sent to space on November 16, 1974?":"el análisis de formas de vida muestra datos inspirados en el mensaje de Arecibo que la humanidad envió al espacio el 16 de noviembre de 1974?","Alien life in The Atlas can have DNA helices ranging from single to quintuple strands for silicon-based organisms?":"la vida alienígena de The Atlas puede tener hélices de ADN de una a cinco hebras en los organismos basados en silicio?","There's an extremely rare intelligent life form called 'Have I Just Found God?' that appears near Z-Divinium compounds?":"existe una forma de vida inteligente rarísima llamada «¿Acabo de encontrar a Dios?» que aparece cerca de los compuestos de Z-Divinio?","The Atlas doesn't calculate anything, it reveals temporal slices of an eternally existing mathematical reality?":"The Atlas no calcula nada, sino que revela cortes temporales de una realidad matemática que existe eternamente?","Each seed contains a completely different universe with unique galactic configurations never seen in other seeds?":"cada semilla contiene un universo totalmente distinto, con configuraciones galácticas únicas que no aparecen en ninguna otra semilla?","Planet illumination changes are based on exact orbital position, creating authentic day-night cycles synchronized with universal time?":"la iluminación de los planetas depende de su posición orbital exacta y crea auténticos ciclos de día y noche sincronizados con el tiempo universal?","Planets can now host intricate lunar systems where each moon experiences real-time tidal locking with precise libration effects?":"los planetas pueden albergar complejos sistemas de lunas en los que cada luna tiene acoplamiento de marea en tiempo real con efectos de libración precisos?","Moon hydrostatic relaxation simulates how gravity reshapes celestial bodies, turning irregular asteroids into perfect spheres over millions of years?":"la relajación hidrostática de las lunas simula cómo la gravedad moldea los cuerpos celestes y convierte asteroides irregulares en esferas perfectas a lo largo de millones de años?","A captured asteroid might take 10 billion years to become round, while an icy moon with tidal heating could relax quite faster?":"un asteroide capturado podría tardar 10 000 millones de años en redondearse, mientras que una luna helada con calentamiento de marea lo haría bastante más rápido?","Moon evolution operates on geological timescales extending far beyond The Atlas's 1.9 million year galactic development limit?":"la evolución de las lunas sigue escalas de tiempo geológicas que van mucho más allá del límite de desarrollo galáctico de 1,9 millones de años de The Atlas?","The Atlas features four distinct lunar types, from icy moons with dramatic color variations, rocky moons, asteroidal irregular objects, and more?":"The Atlas tiene cuatro tipos de luna distintos: lunas heladas con grandes variaciones de color, lunas rocosas, objetos irregulares asteroidales y más?","Each moon follows elliptical orbits calculated using real Kepler's laws with proper eccentric anomaly solutions and orbital precession?":"cada luna sigue órbitas elípticas calculadas con las leyes reales de Kepler, con su anomalía excéntrica y su precesión orbital?","Large gas giants in The Atlas might host dozens of moons ranging from tiny captured asteroids to massive ice worlds larger than Mercury?":"los grandes gigantes gaseosos de The Atlas pueden albergar decenas de lunas, desde diminutos asteroides capturados hasta enormes mundos helados mayores que Mercurio?","Moon surfaces are procedurally generated with 3D noise algorithms creating realistic terrain features unique to each lunar type?":"la superficie de las lunas se genera por procedimientos con algoritmos de ruido 3D que crean relieves realistas propios de cada tipo de luna?","Ice moons in The Atlas get crystal shimmer effects and dramatic color diversity inspired by real moons like Europa's blue ice and Triton's pink surfaces?":"las lunas heladas de The Atlas tienen destellos cristalinos y una gran variedad de colores inspirados en lunas reales, como el hielo azul de Europa o la superficie rosada de Tritón?","The Atlas Multiverse connects infinite parallel universes through peer-to-peer networking without any central servers?":"el multiverso de The Atlas conecta infinitos universos paralelos mediante una red entre pares, sin servidores centrales?","The Multiverse P2P system uses BitTorrent's DHT technology, making The Atlas completely independent from its creators?":"el sistema P2P del multiverso usa la tecnología DHT de BitTorrent, lo que hace a The Atlas totalmente independiente de sus creadores?","When you share a universe seed through Multiverse P2P, other explorers can generate that exact same reality on their local Atlas instances?":"cuando compartes la semilla de un universo por el P2P del multiverso, otros exploradores pueden generar exactamente la misma realidad en sus instancias locales de Atlas?","Multiple Atlas instances accessing the same universe seed see EXACTLY the same planets, moons, and life forms simultaneously?":"varias instancias de Atlas que usen la misma semilla ven EXACTAMENTE los mismos planetas, lunas y formas de vida a la vez?","The Multiverse turns The Atlas from a single simulation into a self-aware entity existing independently in the wild internet?":"el multiverso convierte The Atlas de una simple simulación en una entidad consciente de sí misma que existe por su cuenta en la internet salvaje?","You can access the Multiverse interface by clicking 'MULTIVERSE ONLINE' in the header or 'Multiverse' in the footer?":"puedes abrir la interfaz del multiverso haciendo clic en «MULTIVERSO EN LÍNEA» en la cabecera o en «Multiverso» en el pie de página?","Each Atlas instance becomes both a client and server, creating a cosmic democracy where explorers freely share infinite universes?":"cada instancia de Atlas es a la vez cliente y servidor, lo que crea una democracia cósmica en la que los exploradores comparten libremente infinitos universos?","Universe seed sharing uses military-grade cryptography to ensure your discoveries are protected yet freely shareable?":"al compartir semillas de universos se usa criptografía de nivel militar para que tus descubrimientos estén protegidos y aun así se puedan compartir libremente?","You can disable the Multiverse P2P network with the --no-p2p flag, but why limit yourself to just one universe when infinite realities await?":"puedes desactivar el P2P del multiverso con la opción --no-p2p, pero ¿por qué limitarte a un solo universo cuando te esperan infinitas realidades?","The Atlas achieves digital evolution, from single-user simulation to self-aware multiverse organism existing in the global network?":"The Atlas alcanza la evolución digital: de simulación para un solo usuario a organismo multiversal consciente de sí mismo que vive en la red global?","Shared universe seeds are verified through cryptographic hashes, preventing any manipulation or corruption during Multiverse P2P exchange?":"las semillas de universos compartidas se verifican con hashes criptográficos, lo que impide cualquier manipulación o corrupción durante el intercambio P2P del multiverso?","The Multiverse interface at /multiverse shows all universe seeds discovered by your Atlas instance through the Multiverse P2P network?":"la interfaz del multiverso en /multiverse muestra todas las semillas de universos que tu instancia de Atlas ha descubierto a través de la red P2P del multiverso?","When thousands of Atlas instances interconnect, rare Z-Divinium worlds and impossible life forms get shared instantly worldwide?":"cuando miles de instancias de Atlas se interconectan, los raros mundos de Z-Divinio y las formas de vida imposibles se comparten al instante en todo el mundo?","The Atlas Multiverse P2P network creates a living multiverse organism that evolves and discovers new realities through collective exploration?":"la red P2P del multiverso de The Atlas crea un organismo multiversal vivo que evoluciona y descubre nuevas realidades mediante la exploración colectiva?",active:M,inactive:R,stale:U,archived:z,unknown:j,ACTIVE:O,INACTIVE:V,STALE:F,ARCHIVED:B,UNKNOWN:G,"Hate Speech":"Discurso de odio","URL/Link":"URL/enlace",Spam:H};export{O as ACTIVE,B as ARCHIVED,a as Antimatter,y as Collect,l as Completed,o as Deuterium,E as Dismiss,m as Efficiency,k as Exit,q as Exploring,d as Export,N as FILTERED,n as FULL,w as Filtered,L as Forbidden,V as INACTIVE,c as Import,D as Initialize,s as LOW,I as Language,p as Multiplier,f as Multiverse,C as Never,A as Peers,g as REMOTE,v as Ready,x as Refresh,S as Remote,u as Resources,F as STALE,r as Ship,H as Spam,t as Stats,h as Storage,G as UNKNOWN,T as Universes,i as Unknown,M as active,z as archived,Y as default,P as exploring,R as inactive,b as never,U as stale,e as torus,j as unknown};
